-- Password hashes are generated by PasswordUtil in DatabaseInitializer.
-- This script seeds products after the seller account exists.
-- The Java initializer creates the demo users with BCrypt and then runs these inserts.

INSERT INTO products (seller_id, name, description, price, stock_qty, category, image_url)
SELECT id, 'Wireless Mouse', 'Ergonomic wireless mouse', 699.00, 25, 'Electronics', 'https://example.com/mouse.jpg'
FROM users WHERE email = 'seller@jackmart.local'
AND NOT EXISTS (SELECT 1 FROM products WHERE name = 'Wireless Mouse');

INSERT INTO products (seller_id, name, description, price, stock_qty, category, image_url)
SELECT id, 'USB-C Cable', 'Durable USB-C charging cable', 299.00, 50, 'Accessories', 'https://example.com/cable.jpg'
FROM users WHERE email = 'seller@jackmart.local'
AND NOT EXISTS (SELECT 1 FROM products WHERE name = 'USB-C Cable');

INSERT INTO products (seller_id, name, description, price, stock_qty, category, image_url)
SELECT id, 'Notebook', 'College ruled notebook', 120.00, 100, 'Stationery', 'https://example.com/notebook.jpg'
FROM users WHERE email = 'seller@jackmart.local'
AND NOT EXISTS (SELECT 1 FROM products WHERE name = 'Notebook');
